  a) $\left(x - 4\right)^{3} \quad\quad$ b) $\left(4 x - 5 y\right)^{3} \quad\quad$ c) $\left(4 - x\right)^{3} \quad\quad$ 
\loigiai{
a) $\left(x - 4\right)^{3} = x^{3} - 12 x^{2} + 48 x - 64$\\
b) $\left(4 x - 5 y\right)^{3} = 64 x^{3} - 240 x^{2} y + 300 x y^{2} - 125 y^{3}$\\
c) $\left(4 - x\right)^{3}=- x^{3} + 12 x^{2} - 48 x + 64$
}\end{ex}

\begin{ex}%[8D2N2]
Triển khai biểu thức sau theo hằng đẳng thức:

  a) $\left(x + 2\right)^{3} \quad\quad$ b) $\left(x - y\right)^{3} \quad\quad$ c) $\left(5 - 4 x\right)^{3} \quad\quad$ 
\loigiai{
a) $\left(x + 2\right)^{3} = x^{3} + 6 x^{2} + 12 x + 8$\\
b) $\left(x - y\right)^{3} = x^{3} - 3 x^{2} y + 3 x y^{2} - y^{3}$\\
c) $\left(5 - 4 x\right)^{3}=- 64 x^{3} + 240 x^{2} - 300 x + 125$
}\end{ex}

\begin{ex}%[8D2N2]
Triển khai biểu thức sau theo hằng đẳng thức:

  a) $\left(3 x - 4\right)^{3} \quad\quad$ b) $\left(4 x - 4 y\right)^{3} \quad\quad$ c) $\left(5 - x\right)^{3} \quad\quad$ 
\loigiai{
a) $\left(3 x - 4\right)^{3} = 27 x^{3} - 108 x^{2} + 144 x - 64$\\
b) $\left(4 x - 4 y\right)^{3} = 64 x^{3} - 192 x^{2} y + 192 x y^{2} - 64 y^{3}$\\
c) $\left(5 - x\right)^{3}=- x^{3} + 15 x^{2} - 75 x + 125$
}\end{ex}

\begin{ex}%[8D2N2]
Triển khai biểu thức sau theo hằng đẳng thức:

  a) $\left(x - 5\right)^{3} \quad\quad$ b) $\left(x - 5 y\right)^{3} \quad\quad$ c) $\left(2 - 5 x\right)^{3} \quad\quad$ 
\loigiai{
a) $\left(x - 5\right)^{3} = x^{3} - 15 x^{2} + 75 x - 125$\\
b) $\left(x - 5 y\right)^{3} = x^{3} - 15 x^{2} y + 75 x y^{2} - 125 y^{3}$\\
c) $\left(2 - 5 x\right)^{3}=- 125 x^{3} + 150 x^{2} - 60 x + 8$
}\end{ex}

\begin{ex}%[8D2N2]
Triển khai biểu thức sau theo hằng đẳng thức:

  a) $\left(5 x - 1\right)^{3} \quad\quad$ b) $\left(x - 2 y\right)^{3} \quad\quad$ c) $\left(4 - x\right)^{3} \quad\quad$ 
\loigiai{
a) $\left(5 x - 1\right)^{3} = 125 x^{3} - 75 x^{2} + 15 x - 1$\\
b) $\left(x - 2 y\right)^{3} = x^{3} - 6 x^{2} y + 12 x y^{2} - 8 y^{3}$\\
c) $\left(4 - x\right)^{3}=- x^{3} + 12 x^{2} - 48 x + 64$
}\end{ex}

\begin{ex}%[8D2N2]
Triển khai biểu thức sau theo hằng đẳng thức:

  a) $\left(3 x - 2\right)^{3} \quad\quad$ b) $\left(3 x - 2 y\right)^{3} \quad\quad$ c) $\left(4 - 3 x\right)^{3} \quad\quad$ 
\loigiai{
a) $\left(3 x - 2\right)^{3} = 27 x^{3} - 54 x^{2} + 36 x - 8$\\
b) $\left(3 x - 2 y\right)^{3} = 27 x^{3} - 54 x^{2} y + 36 x y^{2} - 8 y^{3}$\\
c) $\left(4 - 3 x\right)^{3}=- 27 x^{3} + 108 x^{2} - 144 x + 64$
}\end{ex}

\begin{ex}%[8D2N2]
Triển khai biểu thức sau theo hằng đẳng thức:

  a) $\left(2 x + 1\right)^{3} \quad\quad$ b) $\left(2 x + 4 y\right)^{3} \quad\quad$ c) $\left(2 - 4 x\right)^{3} \quad\quad$ 
\loigiai{
a) $\left(2 x + 1\right)^{3} = 8 x^{3} + 12 x^{2} + 6 x + 1$\\
b) $\left(2 x + 4 y\right)^{3} = 8 x^{3} + 48 x^{2} y + 96 x y^{2} + 64 y^{3}$\\
c) $\left(2 - 4 x\right)^{3}=- 64 x^{3} + 96 x^{2} - 48 x + 8$
}\end{ex}

